/// <reference types="next" />
/// <reference types="next/image-types/global" />

// NOTE: This file should not be edited
// see https://nextjs.org/docs/basic-features/typescript for more information.

import { promises as fs } from "node:fs";
import path from "node:path";

export type DevQuery = {
  id: string;
  text: string;
};

let cachedQueries: DevQuery[] | null = null;

function findQueriesFile(): string {
  // The queries TSV is co-located with the Next.js app (frontend/msmarco-v1-passage.dev.queries.tsv).
  // We look first in CWD, then in the directory above process.cwd() so the app works
  // when started from inside the frontend directory or from the project root.
  const candidates = [
    path.join(process.cwd(), "msmarco-v1-passage.dev.queries.tsv"),
    path.join(process.cwd(), "..", "msmarco-v1-passage.dev.queries.tsv"),
  ];
  for (const candidate of candidates) {
    try {
      // eslint-disable-next-line @typescript-eslint/no-require-imports
      require("node:fs").accessSync(candidate);
      return candidate;
    } catch {
      // try next
    }
  }
  return candidates[0];
}

export async function loadDevQueries(): Promise<DevQuery[]> {
  if (cachedQueries) {
    return cachedQueries;
  }
  const file = findQueriesFile();
  const raw = await fs.readFile(file, "utf8");
  const queries: DevQuery[] = [];
  for (const line of raw.split(/\r?\n/)) {
    if (!line) continue;
    const tab = line.indexOf("\t");
    if (tab < 0) continue;
    const id = line.slice(0, tab).trim();
    const text = line.slice(tab + 1).trim();
    if (!id || !text) continue;
    queries.push({ id, text });
  }
  cachedQueries = queries;
  return queries;
}

// Configuration for talking to the Anserini REST backend.

export type AnseriniConfig = {
  baseUrl: string;
  index: string;
};

const DEFAULT_INDEX = "msmarco-v1-passage";
const DEFAULT_BACKEND_PORT = "8080";

export function getAnseriniConfig(): AnseriniConfig {
  // Allow operators to point the frontend at any Anserini REST server.
  // ANSERINI_URL takes precedence; otherwise build from ANSERINI_PORT (default 8080)
  // so the application can be configured purely through environment variables.
  const explicitUrl = process.env.ANSERINI_URL;
  const port = process.env.ANSERINI_PORT ?? DEFAULT_BACKEND_PORT;
  const baseUrl = (explicitUrl && explicitUrl.trim().length > 0
    ? explicitUrl.replace(/\/+$/, "")
    : `http://localhost:${port}`);

  const index = process.env.ANSERINI_INDEX ?? DEFAULT_INDEX;
  return { baseUrl, index };
}

import { NextRequest, NextResponse } from "next/server";
import { loadDevQueries } from "@/lib/queries";

export const dynamic = "force-dynamic";

function sampleWithoutReplacement<T>(arr: T[], n: number): T[] {
  const copy = arr.slice();
  const out: T[] = [];
  const count = Math.min(n, copy.length);
  for (let i = 0; i < count; i++) {
    const idx = Math.floor(Math.random() * (copy.length - i));
    out.push(copy[idx]);
    // Swap chosen element to the end so we don't pick it again.
    const last = copy.length - i - 1;
    [copy[idx], copy[last]] = [copy[last], copy[idx]];
  }
  return out;
}

export async function GET(req: NextRequest) {
  const url = new URL(req.url);
  const countParam = url.searchParams.get("count");
  let count = Number.parseInt(countParam ?? "5", 10);
  if (!Number.isFinite(count) || count < 1) count = 5;
  if (count > 50) count = 50;

  try {
    const queries = await loadDevQueries();
    if (queries.length === 0) {
      return NextResponse.json(
        { error: "Dev queries file is empty or missing." },
        { status: 500 },
      );
    }
    const samples = sampleWithoutReplacement(queries, count);
    return NextResponse.json({ samples });
  } catch (err) {
    return NextResponse.json(
      { error: "Failed to load dev queries: " + (err as Error).message },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getAnseriniConfig } from "@/lib/anserini";

export const dynamic = "force-dynamic";

type AnseriniSearchResponse = {
  api?: string;
  index?: string;
  query?: { text?: string };
  candidates?: Array<{
    docid: string;
    score: number;
    rank: number;
    doc: string;
  }>;
  error?: string;
};

export async function GET(req: NextRequest) {
  const url = new URL(req.url);
  const query = (url.searchParams.get("query") ?? "").trim();
  const hitsParam = url.searchParams.get("hits");
  let hits = Number.parseInt(hitsParam ?? "10", 10);
  if (!Number.isFinite(hits) || hits < 1) hits = 10;
  if (hits > 100) hits = 100;

  if (!query) {
    return NextResponse.json(
      { error: "Query is required." },
      { status: 400 },
    );
  }

  const { baseUrl, index } = getAnseriniConfig();
  const upstream = new URL(`${baseUrl}/v1/${index}/search`);
  upstream.searchParams.set("query", query);
  upstream.searchParams.set("hits", String(hits));

  let upstreamRes: Response;
  try {
    upstreamRes = await fetch(upstream.toString(), {
      method: "GET",
      headers: { Accept: "application/json" },
      // The Anserini REST server does not currently support caching of search
      // results, so revalidate on every call.
      cache: "no-store",
    });
  } catch (err) {
    return NextResponse.json(
      {
        error:
          "Could not reach the Anserini REST backend at " +
          baseUrl +
          ". Is the server running? (" +
          (err as Error).message +
          ")",
      },
      { status: 502 },
    );
  }

  const text = await upstreamRes.text();
  let parsed: AnseriniSearchResponse = {};
  try {
    parsed = text.length > 0 ? (JSON.parse(text) as AnseriniSearchResponse) : {};
  } catch {
    return NextResponse.json(
      {
        error:
          "Anserini returned a non-JSON response (HTTP " +
          upstreamRes.status +
          ").",
      },
      { status: 502 },
    );
  }

  if (!upstreamRes.ok) {
    return NextResponse.json(
      {
        error: parsed.error ?? `Anserini returned HTTP ${upstreamRes.status}.`,
      },
      { status: upstreamRes.status },
    );
  }

  return NextResponse.json({
    query,
    index,
    backend: baseUrl,
    candidates: parsed.candidates ?? [],
  });
}

